SELECT *, STDDEV_SAMP(credit_limit) OVER w_part AS segment_stddev_samp_credit_limit, STDDEV_SAMP(age) OVER w_part_2 AS segment_stddev_samp_age, MIN(age) OVER (PARTITION BY city) AS city_min_age, NTILE(3) OVER (PARTITION BY country ORDER BY credit_limit DESC, id) AS credit_limit_bucket, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY country), 4) AS credit_limit_share FROM customers WINDOW w_part AS (PARTITION BY segment), w_part_2 AS (PARTITION BY segment, country);
